import React from "react";
import { render, fireEvent, screen } from "@testing-library/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import Radio from "../Radio";
import * as stories from "./RadioGroup.stories";
import RadioGroup from "./RadioGroup";

const { Basic } = composeStories(stories) as any;

describe("RadioGroup", () => {
  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("should call onChange when uncontrolled", () => {
    const handleChange = jest.fn();
    render(
      <RadioGroup onChange={handleChange}>
        <Radio value="A" label="A" />
        <Radio value="B" label="B" />
        <Radio value="C" label="C" />
      </RadioGroup>
    );

    fireEvent.click(screen.getByText("A"));
    expect(handleChange).toHaveBeenCalledTimes(1);
    expect(handleChange).toHaveBeenLastCalledWith(expect.anything(), "A");

    fireEvent.click(screen.getByText("B"));
    expect(handleChange).toHaveBeenCalledTimes(2);
    expect(handleChange).toHaveBeenLastCalledWith(expect.anything(), "B");
  });

  it("should handle a default value when uncontrolled", () => {
    const handleChange = jest.fn();
    render(
      <RadioGroup defaultValue="B" onChange={handleChange}>
        <Radio value="A" label="A" />
        <Radio value="B" label="B" />
        <Radio value="C" label="C" />
      </RadioGroup>
    );
    expect(screen.getByLabelText("B")).toBeChecked();
    fireEvent.click(screen.getByText("A"));
    expect(handleChange).toHaveBeenCalledTimes(1);
    expect(handleChange).toHaveBeenLastCalledWith(expect.anything(), "A");
  });

  it("should call onChange when controlled", () => {
    const handleChange = jest.fn();
    render(
      <RadioGroup value="" onChange={handleChange}>
        <Radio value="A" label="A" />
        <Radio value="B" label="B" />
        <Radio value="C" label="C" />
      </RadioGroup>
    );

    fireEvent.click(screen.getByText("B"));
    expect(handleChange).toHaveBeenCalledTimes(1);
    expect(handleChange).toHaveBeenLastCalledWith(expect.anything(), "B");
  });

  it("passes through props", () => {
    render(<RadioGroup data-testid="radiogroup"></RadioGroup>);
    expect(screen.queryByRole("radiogroup")).toHaveAttribute(
      "data-testid",
      "radiogroup"
    );
  });

  it("generate unique name if unspecified", () => {
    render(
      <RadioGroup>
        <Radio value="A" label="A" />
      </RadioGroup>
    );
    const radio = screen.queryByRole("radio") as HTMLElement;
    expect(radio.getAttribute("name")).toMatch(/^radiogroup-/);
  });

  it("use name prop if specified", () => {
    render(
      <RadioGroup name="groupname">
        <Radio value="A" label="A" />
      </RadioGroup>
    );
    expect(screen.queryByRole("radio")).toHaveAttribute("name", "groupname");
  });

  it("allow number and string values", () => {
    const handleChange = jest.fn();
    render(
      <RadioGroup onChange={handleChange}>
        <Radio value={10} label="number" />
        <Radio value="20" label="string" />
      </RadioGroup>
    );
    const radios = screen.queryAllByRole("radio");

    fireEvent.click(radios[1]);
    expect(radios[1]).toBeChecked();
    expect(handleChange).toHaveBeenCalledTimes(1);
    expect(handleChange).toHaveBeenLastCalledWith(expect.anything(), "20");

    fireEvent.click(radios[0]);
    expect(radios[0]).toBeChecked();
    expect(handleChange).toHaveBeenCalledTimes(2);
    // number value is converted to string internally as <input type="radio"> only supports string
    expect(handleChange).toHaveBeenLastCalledWith(expect.anything(), "10");
  });
});
